	/** A subquery whose solutions are (c = urn:k:i, cnt = i + 1) for i in 0..rows-1; {@code onAdvance} sees each i. */
	private static NativeSubqueryPlan subquery(int rows, IntConsumer onAdvance) {
		QueryEvaluationStep step = input -> new CloseableIteration<BindingSet>() {
			int next;

			@Override
			public boolean hasNext() {
				return next < rows;
			}

			@Override
			public BindingSet next() {
				int i = next++;
				onAdvance.accept(i);
				QueryBindingSet solution = new QueryBindingSet();
				solution.setBinding("c", key(i));
				solution.setBinding("cnt", VF.createLiteral(i + 1));
				return solution;
			}

			@Override
			public void close() {
			}
		};
		return new NativeSubqueryPlan(step, new int[] { 0, 1 }, new String[] { "c", "cnt" }, new int[0],
				new String[0], new String[0], new String[0], null, null,
				worker -> new NativeSubqueryPlan.BoundExecution(
						step, null, null));
	}

	/** Emits one row per listed id, binding slot 0 (and honouring an already bound slot 0). */
	private static final class ListProbe implements SlotPlan {
		final long[] ids;
		final AtomicInteger produced = new AtomicInteger();
		final AtomicBoolean closed = new AtomicBoolean();
		final IntConsumer onRow;

		ListProbe(long[] ids, IntConsumer onRow) {
			this.ids = ids;
			this.onRow = onRow;
		}

		@Override
		public RowCursor open(RowState row) {
			return new RowCursor() {
				int next;
				int mark = -1;

				@Override
				public boolean next() {
					if (mark >= 0) {
						row.rollback(mark);
						mark = -1;
					}
					while (next < ids.length) {
						int index = next++;
						produced.incrementAndGet();
						onRow.accept(index);
						int before = row.mark();
						if (row.bind(0, ids[index])) {
							mark = before;
							return true;
						}
						row.rollback(before);
					}
					return false;
				}

				@Override
				public void close() {
					closed.set(true);
				}
			};
		}

		@Override
		public long producedMask() {
			return 1L;
		}
	}

	/** A provider that answers every key with a fixed lookup and records its session lifecycle. */
	private static final class StubProvider implements NativeKeyedSubqueryProvider {
		final AtomicInteger sessionsOpened = new AtomicInteger();
		final AtomicInteger sessionsClosed = new AtomicInteger();
		final Lookup answer;

		StubProvider(Lookup answer) {
			this.answer = answer;
		}

		@Override
		public String tag() {
			return "stub";
		}

		@Override
		public NativeKeyedSubqueryProvider forWorker(NativeSubqueryPlan workerSub) {
			return this;
		}

		@Override
		public Session open(RowState row, NativeKeyedSubqueryJoinPlan plan) throws IOException {
			sessionsOpened.incrementAndGet();
			return new Session() {
				boolean fresh;

				@Override
				public Lookup seek(long keyId) {
					fresh = answer == Lookup.MATCH;
					return answer;
				}

				@Override
				public boolean nextMatch() {
					boolean result = fresh;
					fresh = false;
					return result;
				}

				@Override
				public boolean bindMatch(RowState target) {
					return true;
				}

				@Override
				public void close() {
					sessionsClosed.incrementAndGet();
				}
			};
		}
	}

	@Test
	public void cancelledProbeStopsTheCursorAndClosesProbeAndSession() throws IOException {
		int total = 5000;
		RowState row = newRow(null);
		ListProbe probe = new ListProbe(LongStream.rangeClosed(1, total).toArray(), index -> {
			if (index == 10) {
				row.cancellation.requestCancellation();
			}
		});
		StubProvider provider = new StubProvider(NativeKeyedSubqueryProvider.Lookup.ABSENT);
		NativeKeyedSubqueryJoinPlan plan = new NativeKeyedSubqueryJoinPlan(probe, subquery(1, i -> {
		}), provider, 0, 0L, null, false);

		RowCursor cursor = plan.open(row);
		boolean threw = false;
		try {
			while (cursor.next()) {
				// no key matches, so nothing is emitted
			}
		} catch (RuntimeException cancelled) {
			threw = true;
		}
		assertThat(probe.produced.get()).as("the probe must stop shortly after cancellation (threw=" + threw + ")")
				.isLessThan(total);
		cursor.close();
		assertThat(probe.closed).as("the probe cursor is closed").isTrue();
		assertThat(provider.sessionsOpened).hasValue(1);
		assertThat(provider.sessionsClosed).as("the session is closed exactly once").hasValue(1);
		cursor.close();
		assertThat(provider.sessionsClosed).as("close is idempotent").hasValue(1);
	}

	@Test
	public void cancelledGenericBuildPublishesNothingAndAFreshEvaluationRebuilds() throws IOException {
		long buildsBefore = NativeKeyedSubqueryJoinPlan.GENERIC_INDEX_BUILDS.get();

		SyntheticValueSource cancelledSource = newSource();
		AtomicReference<RowState> cancelledRow = new AtomicReference<>();
		NativeSubqueryPlan cancelledSub = subquery(100, i -> {
			if (i == 50) {
				cancelledRow.get().cancellation.requestCancellation();
			}
		});
		RowState row = newRow(cancelledSource);
		cancelledRow.set(row);
		NativeKeyedSubqueryIndex cancelledProvider = new NativeKeyedSubqueryIndex(cancelledSub);
		NativeKeyedSubqueryJoinPlan cancelledPlan = new NativeKeyedSubqueryJoinPlan(
				new ListProbe(new long[0], i -> {
				}), cancelledSub, cancelledProvider, 0, 0L, null, false);
		try {
			assertThatThrownBy(() -> cancelledProvider.open(row, cancelledPlan))
					.isInstanceOf(RuntimeException.class);
			assertThat(NativeKeyedSubqueryJoinPlan.GENERIC_INDEX_BUILDS.get() - buildsBefore)
					.as("a cancelled build must not complete or publish an index")
					.isZero();
		} finally {
			cancelledSource.executionContext().close();
		}

		SyntheticValueSource freshSource = newSource();
		try {
			NativeSubqueryPlan freshSub = subquery(100, i -> {
			});
			RowState freshRow = newRow(freshSource);
			NativeKeyedSubqueryIndex freshProvider = new NativeKeyedSubqueryIndex(freshSub);
			NativeKeyedSubqueryJoinPlan freshPlan = new NativeKeyedSubqueryJoinPlan(new ListProbe(new long[0], i -> {
			}), freshSub, freshProvider, 0, 0L, null, false);
			try (NativeKeyedSubqueryProvider.Session session = freshProvider.open(freshRow, freshPlan)) {
				assertThat(NativeKeyedSubqueryJoinPlan.GENERIC_INDEX_BUILDS.get() - buildsBefore)
						.as("a fresh evaluation rebuilds the index once")
						.isEqualTo(1L);
				long present = freshSub.internTerm(freshRow, key(7), 0);
				long absent = freshSub.internTerm(freshRow, key(700), 0);
				assertThat(session.seek(present)).isEqualTo(NativeKeyedSubqueryProvider.Lookup.MATCH);
				assertThat(session.nextMatch()).isTrue();
				assertThat(session.bindMatch(freshRow)).isTrue();
				assertThat(freshRow.view.getValue("cnt")).isEqualTo(VF.createLiteral(8));
				assertThat(session.seek(absent)).isEqualTo(NativeKeyedSubqueryProvider.Lookup.ABSENT);
			}
		} finally {
			freshSource.executionContext().close();
		}
	}

	@Test
	public void cancelledAdjacencyDecodeStopsTheScanAndClosesTheCursors() throws IOException {
		LmdbAdjacencyRootCounterTest.Fixture fixture = new LmdbAdjacencyRootCounterTest.Fixture(false);
		fixture.root(10, LongStream.range(100, 700).toArray());
		AtomicInteger polls = new AtomicInteger();
		LmdbAdjacencyRootCounter counter = fixture.counter(() -> {
			if (polls.incrementAndGet() > 1) {
				throw new IllegalStateException("query cancelled");
			}
		});
		try {
			assertThatThrownBy(() -> counter.distinctNeighbors(10)).isInstanceOf(IllegalStateException.class)
					.hasMessageContaining("cancelled");
		} finally {
			counter.close();
		}
		assertThat(fixture.cursors).as("both the root and the decode cursor were opened").hasSize(2);
		assertThat(fixture.cursors).allMatch(cursor -> cursor.closed);
		assertThat(counter.decodeCounts()).isEqualTo(1L);
	}

