	@Test
	public void workerBindingForksTheSubqueryAndTheProviderOnce() throws IOException {
		SyntheticValueSource source = newSource();
		try {
			NativeSubqueryPlan sub = subquery(3, i -> {
			});
			NativeKeyedSubqueryIndex provider = new NativeKeyedSubqueryIndex(sub);
			NativeKeyedSubqueryJoinPlan plan = new NativeKeyedSubqueryJoinPlan(SlotPlan.singleton(), sub, provider, 0,
					0L, null, true);
			assertThat(NativeWorkerPlanBinder.canBind(plan)).isTrue();
			long bindingsBefore = NativeSubqueryPlan.WORKER_BINDINGS.get();
			try (NativeWorkerPlanBinder binder = new NativeWorkerPlanBinder(
					new NativeScalarPlan.WorkerContext(source, null, null))) {
				SlotPlan bound = binder.bind(plan);
				assertThat(bound).isInstanceOf(NativeKeyedSubqueryJoinPlan.class).isNotSameAs(plan);
				NativeKeyedSubqueryJoinPlan keyed = (NativeKeyedSubqueryJoinPlan) bound;
				assertThat(keyed.subPlan).as("the subquery is forked for the worker").isNotSameAs(sub);
				assertThat(keyed.provider).as("the provider is rebound to the fork")
						.isNotSameAs(provider)
						.isInstanceOf(NativeKeyedSubqueryIndex.class);
				assertThat(keyed.keySlot).isEqualTo(plan.keySlot);
				assertThat(keyed.payloadSlots).containsExactly(1);
				assertThat(NativeSubqueryPlan.WORKER_BINDINGS.get() - bindingsBefore).isEqualTo(1L);
			}
		} finally {
			source.executionContext().close();
		}
	}

	@Test
	public void requiredEncounterOrderKeepsTheSubqueryMajorOrder() throws IOException {
		long[] probeOrder = new long[3];
		List<String> keyedOrder = run(false, probeOrder);
		long keyedOpens = NativeKeyedSubqueryJoinPlan.KEYED_OPENS.get();
		List<String> encounterOrder = run(true, probeOrder);

		assertThat(NativeKeyedSubqueryJoinPlan.KEYED_OPENS.get())
				.as("the encounter-order open delegates to the ordinary join instead of the keyed cursor")
				.isEqualTo(keyedOpens);
		assertThat(keyedOrder).as("keyed path is probe-major").containsExactly("urn:k:2", "urn:k:0", "urn:k:1");
		assertThat(encounterOrder).as("delegation keeps the subquery-major order")
				.containsExactly("urn:k:0", "urn:k:1", "urn:k:2");
	}

	private static List<String> run(boolean encounterOrderRequired, long[] scratch) throws IOException {
		SyntheticValueSource source = newSource();
		try {
			NativeSubqueryPlan sub = subquery(3, i -> {
			});
			RowState row = newRow(source);
			row.encounterOrderRequired = encounterOrderRequired;
			// the probe lists the keys in reverse subquery order
			long[] ids = { source.internComputedValue(key(2)), source.internComputedValue(key(0)),
					source.internComputedValue(key(1)) };
			ListProbe probe = new ListProbe(ids, i -> {
			});
			NativeKeyedSubqueryJoinPlan plan = new NativeKeyedSubqueryJoinPlan(probe, sub,
					new NativeKeyedSubqueryIndex(sub), 0, 0L, null, true);
			List<String> keys = new ArrayList<>();
			RowCursor cursor = plan.open(row);
			try {
				while (cursor.next()) {
					keys.add(row.view.getValue("c").stringValue());
					assertThat(row.view.getValue("cnt")).as("the payload is attached on every path").isNotNull();
				}
			} finally {
				cursor.close();
			}
			return keys;
		} finally {
			source.executionContext().close();
		}
	}
